import { describe, expect, it, vi, beforeEach } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';

vi.mock('./supabase.js', () => ({
  supabaseAdmin: {
    from: vi.fn(),
  },
}));

import { supabaseAdmin } from './supabase.js';
import { appendChangeLog } from './repo.js';

const mockInsert = vi.fn();

beforeEach(() => {
  vi.clearAllMocks();
  (supabaseAdmin.from as ReturnType<typeof vi.fn>).mockReturnValue({
    insert: mockInsert,
  });
});

describe('appendChangeLog', () => {
  const entry = {
    Who: 'TestUser',
    Action: 'create' as const,
    Collection: 'virtues',
    ObjectId: 'v-test',
    ObjectName: 'Test Virtue',
    Before: null,
    After: { Id: 'v-test', Name: 'Test Virtue' },
  };

  it('inserts without an id field so database generates the UUID', async () => {
    mockInsert.mockResolvedValue({ error: null });

    await appendChangeLog(entry);

    expect(mockInsert).toHaveBeenCalledTimes(1);
    const insertPayload = mockInsert.mock.calls[0][0];

    expect(insertPayload).not.toHaveProperty('id');

    expect(insertPayload).toEqual({
      at: expect.any(String),
      who: 'TestUser',
      action: 'create',
      collection: 'virtues',
      object_id: 'v-test',
      object_name: 'Test Virtue',
      before: null,
      after: { Id: 'v-test', Name: 'Test Virtue' },
    });
  });

  it('propagates errors from the database insert', async () => {
    const dbError = new Error('Database error');
    mockInsert.mockResolvedValue({ error: dbError });

    await expect(appendChangeLog(entry)).rejects.toThrow('Database error');
  });
});

